import type { Result } from "@/bindings";

/**
 * Unwrap a generated Tauri command result.
 *
 * The commands in `@/bindings` are generated by `tauri-specta` and resolve
 * backend errors as `{ status: "error", error }` instead of rejecting the
 * promise. That means a plain `try/catch` around `await commands.something()`
 * never fires for an ordinary backend failure — the `catch` block is dead code
 * and the user is shown nothing.
 *
 * Call this to convert those results into real exceptions at the call site:
 *
 * ```ts
 * try {
 *   unwrapResult(await commands.deleteHistoryEntry(id));
 * } catch (e) {
 *   toast.error(String(e));
 * }
 * ```
 *
 * Note that a command can *also* reject with a JavaScript `Error` (e.g. a
 * serialization failure). Both paths are therefore covered by a single
 * `try/catch` once this helper is used.
 */
export function unwrapResult<T, E>(result: Result<T, E>): T {
  if (result.status === "error") {
    throw new Error(String(result.error));
  }
  return result.data;
}
